 async function chapterStages(){await ready();const previousStudio=window.SpeciesStudioMode;window.SpeciesStudioMode=false;GameSpeed.set(4);const scenes=[];const finish=()=>{if(battling){session.battle.win('p1');snapshotPartner();busy=false;endBattle();}MoveFX.cancel();};try{for(const context of [{id:'route3',label:'Percorso 3: sentiero',terrain:'path'},{id:'route3',label:'Percorso 3: erba',terrain:'grass'},{id:'route3Dark',label:'Percorso 3: erba scura',terrain:'grass'},{id:'wellspring',label:'Grotta Minerale',terrain:'cave'},{id:'nacrene',label:'Zefiropoli',terrain:'town'}]){finish();const cave=context.id==='wellspring',city=context.id==='nacrene';await startBattle(true,{previewLocation:Object.freeze(context),doubles:!city,p1:[{name:city?'Roggenrola':'Snivy',level:15,moves:[33]},...(!cave&&!city?[{name:'Oshawott',level:15,moves:[33]}]:[])],p2:[{name:city?'Tympole':'Patrat',level:13,moves:[33]},...(!cave&&!city?[{name:'Purrloin',level:13,moves:[10]}]:[])],...(cave?{ally:[{name:'Tepig',level:14,moves:[33]}],secondFoe:[{name:'Purrloin',level:13,moves:[10]}]}:{})});await until(()=>!busy,'chapter stage intro');busy=true;delete arena.dataset.ambient;BattleDiorama.requestAmbientVisibilityAudit();drawArena();BattleScreen.cards();colorCheck(pixels(arena));const ambient=JSON.parse(arena.dataset.ambient||'[]');if(city)check(ambient.length===0,'City must not inherit ambient Pokemon');if(!city){check(ambient.length===(cave?2:3),'Ambient count '+context.id);for(const row of ambient)check(row.visibility?.full>0&&row.visibility.ratio>.7,'Ambient occluded '+context.id+' '+row.species+' '+JSON.stringify(row.visibility));}await wait(0);const controls=document.getElementById('demoControls'),restart=document.getElementById('demoRestart'),rect=e=>{const r=e.getBoundingClientRect();return {id:e.id||e.className,left:r.left,right:r.right,top:r.top,bottom:r.bottom};},bar=rect(controls),cards=[...document.querySelectorAll('#enemyCard,#playerCard,.double-card:not([hidden])')].map(rect),hit=(a,b)=>a.left<b.right&&a.right>b.left&&a.top<b.bottom&&a.bottom>b.top;check(!controls.hidden&&!restart.hidden&&controls.dataset.battle==='true','Full public battle controls not visible');for(const card of cards)check(!hit(bar,card),'Battle controls overlap '+card.id);for(let i=0;i<cards.length;i++)for(let j=0;j<i;j++)check(!hit(cards[i],cards[j]),'HP panels overlap');shot('Fondale finale: '+context.label,arena);scenes.push({id:context.id,terrain:context.terrain,ambient,dimensions:[arena.width,arena.height],double:!city,partner:cave,hud:{bar,cards,restartVisible:true,noOverlaps:true}});}return {scenes};}finally{window.SpeciesStudioMode=previousStudio;finish();GameSpeed.set(1);}}
