 async function doublesReplay(){
  await ready();GameSpeed.set(4);const seen=[],play=MoveFX.play;
  MoveFX.play=async function(...args){const pending=play.apply(this,args);await until(()=>!!MoveFX.active,'live move profile');seen.push({side:args[1],species:MoveFX.active?.profile?.species,actor:DoubleBattles.combatantFor(args[1])?.species.num});return pending;};
  const finish=()=>{if(battling){session.battle.win('p1');snapshotPartner();busy=false;endBattle();}MoveFX.cancel();};
  const choose=async()=>{const promise=turn(0);await until(()=>document.getElementById('bwBattleFooter').dataset.mode==='targets','double target menu');const buttons=[...document.querySelectorAll('#battleTouch button')];check(buttons.filter(b=>(b.getAttribute('aria-label')||'').includes('avversario')).length===2,'Both foes must be selectable');check(buttons.some(b=>(b.getAttribute('aria-label')||'').includes('alleato')),'Ally target missing');buttons.find(b=>(b.getAttribute('aria-label')||'').includes('avversario')).click();await promise;};
  try{for(const multi of [false,true]){const from=seen.length;finish();await startBattle(true,{previewLocation:Object.freeze({id:multi?'wellspring':'route3Dark',label:multi?'Grotta Minerale':'Percorso 3',terrain:multi?'cave':'grass'}),doubles:true,p1:[{name:'Snivy',level:15,moves:[33]},{name:'Oshawott',level:15,moves:[33]}],p2:[{name:'Patrat',level:15,moves:[33]},...(!multi?[{name:'Purrloin',level:15,moves:[10]}]:[])],...(multi?{ally:[{name:'Tepig',level:14,moves:[33]}],secondFoe:[{name:'Purrloin',level:15,moves:[10]}]}:{})});await until(()=>!busy,'double commands ready');const current=session.battle.turn;await choose();if(!multi){check(session.selectionSlot===1&&session.battle.turn===current,'First command prematurely consumed the turn');await choose();}check(session.battle.turn===current+1,'Two commands did not resolve exactly one turn');check(seen.slice(from).some(e=>e.side==='p2'),'Enemy did not animate');if(multi)check(seen.slice(from).some(e=>e.species===498&&e.actor===498),'Komor Tepig used another body/profile');drawArena();BattleScreen.cards();shot(multi?'Lotta con Komor: quattro combattenti e HUD':'Lotta doppia: selezione dei due comandi e bersagli',arena);}
   return {formats:['doubles','multi'],independentCommands:true,foeAndAllyTargets:true,enemyAnimations:true,komorOwnBody:true,animations:seen};
  }finally{MoveFX.play=play;finish();GameSpeed.set(1);}
 }
